def build_dataset(rows, tokenizer, max_len: int):
    """Tokenize each row and produce labels with prompt tokens masked.

    Each row['text'] is the full chat-formatted training text. The
    portion up to and including COMPLETION_MARKER is the prompt; tokens
    after it are the completion (model's target).
    """
    marker_ids = tokenizer.encode(COMPLETION_MARKER, add_special_tokens=False)
    marker_len = len(marker_ids)

    def tokenize(example):
        text = example["text"]
        ids = tokenizer.encode(text, add_special_tokens=False)
        # Truncate from the right (keep prompt + as much completion as
        # fits). For GSM8K none of our seqs exceed 512 anyway.
        ids = ids[:max_len]
        # Find the completion marker in the token ids.
        labels = ids.copy()
        # search for marker_ids subsequence
        pos = -1
        for i in range(len(ids) - marker_len + 1):
            if ids[i : i + marker_len] == marker_ids:
                pos = i + marker_len
                break
        if pos == -1:
            # fall back: train on full text (shouldn't happen with our data)
            pass
        else:
            for j in range(pos):
                labels[j] = -100
        return {"input_ids": ids, "labels": labels, "attention_mask": [1] * len(ids)}

    return Dataset.from_list([tokenize(r) for r in rows])

