def build_dataset(rows, tokenizer, max_len: int):
    """Tokenize each row and produce labels with prompt tokens masked.

    Strategy: locate the `</think>` token (id 151668). Everything up to
    and including it is the prompt. The completion (reasoning + answer)
    starts at the next token. We mask the prompt portion so the loss
    trains only on the model's own output tokens.
    """
    END_THINK_ID = tokenizer.convert_tokens_to_ids("</think>")

    def tokenize(example):
        text = example["text"]
        ids = tokenizer.encode(text, add_special_tokens=False)
        ids = ids[:max_len]
        labels = list(ids)
        # Find LAST occurrence of </think> — that's the assistant's end-of-thinking.
        end_think_pos = -1
        for i, t in enumerate(ids):
            if t == END_THINK_ID:
                end_think_pos = i
        if end_think_pos == -1:
            # No marker — would have been a malformed example. Skip masking.
            pass
        else:
            for j in range(end_think_pos + 1):
                labels[j] = -100
        return {"input_ids": ids, "labels": labels, "attention_mask": [1] * len(ids)}

    return Dataset.from_list([tokenize(r) for r in rows])

